import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { CheckCircle2 } from "lucide-react";

import {
  Screen,
  PrimaryButton,
} from "../components/common/UI";

import "../styles/PaymentSuccess.css";

export default function PaymentSuccess() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /orders/:orderId
    // Get orderId from URL params or context
    setOrder({
      _id: "1",
      public_id: "GR-98312",
      merchant: {
        business_name: "SupaMart Grocers"
      },
      recipient: {
        name: "Amina Otieno"
      },
      total: { kes: "564.00", aud: "6.24" }
    });
    setLoading(false);
  }, [searchParams]);

  if (loading) {
    return <Screen title="Payment Status">Loading...</Screen>;
  }

  return (
    <Screen title="Payment Status">
      <div className="payment-result success-result">
        <CheckCircle2
          size={74}
          color="#188b43"
        />

        <h2>Payment Successful!</h2>

        <p>
          Your order has been sent to {order?.merchant?.business_name}. {order?.recipient?.name} will be notified on WhatsApp.
        </p>

        {order && (
          <div className="panel">
            <div className="summary-line">
              <span>Order</span>
              <b>{order.public_id}</b>
            </div>

            <div className="summary-line">
              <span>Merchant</span>
              <b>{order.merchant.business_name}</b>
            </div>

            <div className="summary-line">
              <span>Total</span>
              <b className="orange">
                KSh {order.total.kes}
                <span className="aud-price">≈ AUD {order.total.aud}</span>
              </b>
            </div>
          </div>
        )}

        <PrimaryButton
          onClick={() => navigate(`/orders/${order?._id}`)}
        >
          Track Order
        </PrimaryButton>

        <button
          className="text-action"
          onClick={() => navigate("/home")}
        >
          Back to Home
        </button>
      </div>
    </Screen>
  );
}
